CREATE TABLE IF NOT EXISTS schema_migrations (id TEXT PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, target_kind TEXT NOT NULL CHECK(target_kind IN ('codex','claude')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS census_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version INTEGER NOT NULL, digest TEXT NOT NULL UNIQUE, baseline TEXT NOT NULL, policy_hash TEXT NOT NULL, observed_at TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_items (id TEXT PRIMARY KEY, snapshot_id TEXT NOT NULL REFERENCES census_snapshots(id), proposal_hash TEXT NOT NULL, target_kind TEXT NOT NULL, baseline TEXT NOT NULL, policy_hash TEXT NOT NULL, action TEXT NOT NULL, scope_json TEXT NOT NULL, forbidden_json TEXT NOT NULL, budget_json TEXT NOT NULL, attempt_id TEXT NOT NULL, deadline TEXT NOT NULL, lease_id TEXT NOT NULL, lease_epoch INTEGER NOT NULL, fencing_token INTEGER NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(proposal_hash));
CREATE TABLE IF NOT EXISTS decision_receipts (receipt_id TEXT PRIMARY KEY, proposal_hash TEXT NOT NULL, payload_json TEXT NOT NULL, public_key TEXT NOT NULL, signature TEXT NOT NULL, expires_at TEXT NOT NULL, max_uses INTEGER NOT NULL CHECK(max_uses = 1), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS receipt_redemptions (receipt_id TEXT PRIMARY KEY REFERENCES decision_receipts(receipt_id), continuation_id TEXT NOT NULL UNIQUE, redeemed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS policy_authorizations (id TEXT PRIMARY KEY, proposal_hash TEXT NOT NULL, policy_hash TEXT NOT NULL, action TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS continuation_acceptances (id TEXT PRIMARY KEY, work_id TEXT NOT NULL UNIQUE REFERENCES work_items(id), proposal_hash TEXT NOT NULL, authorization_kind TEXT NOT NULL, authorization_id TEXT NOT NULL, lease_epoch INTEGER NOT NULL, fencing_token INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (intent_id TEXT PRIMARY KEY, continuation_id TEXT NOT NULL REFERENCES continuation_acceptances(id), kind TEXT NOT NULL, payload_json TEXT NOT NULL, delivered_at TEXT, acked_at TEXT, finalized_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consumer_inbox (intent_id TEXT PRIMARY KEY, consumed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_ledger (seq INTEGER PRIMARY KEY AUTOINCREMENT, work_id TEXT, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_projection (work_id TEXT PRIMARY KEY REFERENCES work_items(id), state TEXT NOT NULL, updated_at TEXT NOT NULL);
